/*
 * Semantic model test for CVE-2019-14835 / commit 060423bfdee3
 * ("vhost: make sure log_num < in_num").
 *
 * This test does NOT build the Linux kernel. It models the exact loop logic of
 * drivers/vhost/vhost.c get_indirect() and vhost_get_vq_desc():
 *
 *     ret = translate_desc(...);          // number of iovecs; 0 for desc.len == 0
 *     if (desc.flags & VRING_DESC_F_WRITE) {
 *             *in_num += ret;
 *             if (unlikely(log)) {                    // OLD (vulnerable)
 *             if (unlikely(log && ret)) {             // NEW (fixed)
 *                     log[*log_num].addr = ...;
 *                     log[*log_num].len  = ...;
 *                     ++*log_num;
 *             }
 *     }
 *
 * The log array is a fixed allocation of UIO_MAXIOV entries (see
 * vhost_dev_alloc_iovecs: kmalloc(sizeof *vq->log * UIO_MAXIOV)).
 * Canary words placed immediately around the modelled array detect the
 * out-of-bounds write that a malicious guest triggers with zero-length input
 * descriptors.
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define UIO_MAXIOV 1024
#define MAGIC_PRE  0x1111111111111111ULL
#define MAGIC_POST 0x2222222222222222ULL

struct vhost_log {
	uint64_t addr;
	uint64_t len;
};

struct blob {
	uint64_t canary_pre[8];
	struct vhost_log log[UIO_MAXIOV];
	uint64_t canary_post[8];
};

/* fixed == 0 : OLD vulnerable guard `if (log)`
 * fixed == 1 : NEW fixed guard `if (log && ret)`
 * ret_fn(i) returns the number of iovecs translate_desc() would return.
 * returns 0 ok, 1 canary clobbered (out-of-bounds), 2 log_num > in_num
 */
static int run(int fixed, int n_desc, unsigned int (*ret_fn)(int), unsigned int *out_log_num,
	       unsigned int *out_in_num)
{
	static struct blob b;
	unsigned int in_num = 0, log_num = 0;
	int log_active = 1; /* vq->log != NULL: VHOST_F_LOG_ALL active */
	int i;
	size_t k;

	for (k = 0; k < 8; k++) {
		b.canary_pre[k] = MAGIC_PRE;
		b.canary_post[k] = MAGIC_POST;
	}
	memset(b.log, 0, sizeof(b.log));

	for (i = 0; i < n_desc; i++) {
		unsigned int ret = ret_fn(i);
		in_num += ret;
		if (fixed) {
			if (log_active && ret) {
				b.log[log_num].addr = (uint64_t)i;
				b.log[log_num].len = ret;
				log_num++;
			}
		} else {
			if (log_active) {
				b.log[log_num].addr = (uint64_t)i;
				b.log[log_num].len = ret;
				log_num++;
			}
		}
	}
	*out_log_num = log_num;
	*out_in_num = in_num;
	for (k = 0; k < 8; k++) {
		if (b.canary_pre[k] != MAGIC_PRE || b.canary_post[k] != MAGIC_POST)
			return 1;
	}
	return (log_num > in_num) ? 2 : 0;
}

static unsigned int zero_len(int i) { (void)i; return 0; }
static unsigned int unit_len(int i) { (void)i; return 1; }
static unsigned int mixed_len(int i) { return (i % 2 == 0) ? 1u : 0u; }

int main(void)
{
	unsigned int log_num, in_num;
	int rc;
	int failures = 0;

	/* Negative path: many zero-length input descriptors, OLD guard. */
	rc = run(0, UIO_MAXIOV + 64, zero_len, &log_num, &in_num);
	printf("OLD guard, %d zero-length desc: rc=%d log_num=%u in_num=%u %s\n",
	       UIO_MAXIOV + 64, rc, log_num, in_num,
	       rc == 1 ? "(out-of-bounds write detected)" : "(no OOB?)");
	if (rc != 1) { printf("  EXPECTED out-of-bounds (rc=1)\n"); failures++; }

	/* Negative path: same input, NEW guard. Must not write past the array. */
	rc = run(1, UIO_MAXIOV + 64, zero_len, &log_num, &in_num);
	printf("NEW guard, %d zero-length desc: rc=%d log_num=%u in_num=%u %s\n",
	       UIO_MAXIOV + 64, rc, log_num, in_num,
	       rc == 0 ? "(in bounds, invariant held)" : "(unexpected)");
	if (rc != 0) { printf("  EXPECTED in-bounds no-op (rc=0)\n"); failures++; }
	if (log_num != 0 || in_num != 0) { printf("  EXPECTED log_num=0 in_num=0\n"); failures++; }

	/* Positive path: non-zero-length descriptors still get logged. */
	rc = run(1, 10, unit_len, &log_num, &in_num);
	printf("NEW guard, 10 unit-length desc: rc=%d log_num=%u in_num=%u %s\n",
	       rc, log_num, in_num, (rc == 0 && log_num == 10 && in_num == 10) ? "(logged as before)" : "(unexpected)");
	if (!(rc == 0 && log_num == 10 && in_num == 10)) { printf("  EXPECTED log_num=10 in_num=10\n"); failures++; }

	/* Positive/mixed: only non-zero descriptors are logged. */
	rc = run(1, 10, mixed_len, &log_num, &in_num);
	printf("NEW guard, 10 mixed desc: rc=%d log_num=%u in_num=%u %s\n",
	       rc, log_num, in_num, (rc == 0 && log_num == 5 && in_num == 5) ? "(invariant held)" : "(unexpected)");
	if (!(rc == 0 && log_num == 5 && in_num == 5)) { printf("  EXPECTED log_num=5 in_num=5\n"); failures++; }

	if (failures) {
		printf("MODEL TEST FAILED (%d)\n", failures);
		return 1;
	}
	printf("MODEL TEST PASSED\n");
	return 0;
}

